package com.shipflow.audit; import java.nio.charset.StandardCharsets; import java.nio.file.*; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class AuditQueryMapperXmlTest { @Test void mapperIsReadOnlyAndFiltersEveryQueryByTenant() throws Exception {String xml=Files.readString(Path.of("src/main/resources/mapper/audit/AuditQueryMapper.xml"),StandardCharsets.UTF_8);assertThat(xml).contains("tenant_id=#{tenantId}","resource_type=#{resourceType}","resource_id=#{resourceId}","operator_user_id=#{operatorId}","occurred_at");assertThat(xml.toUpperCase()).doesNotContain("INSERT ","UPDATE ","DELETE ","SELECT *");} }
